// ---------- helpers de criação de registros ----------
function nextId(list, prefix, pad) {
  let max = 0;
  list.forEach((x) => {
    const m = String(x.id).match(new RegExp(prefix.replace(/[-]/g, "\\-") + "(\\d+)"));
    if (m) max = Math.max(max, parseInt(m[1], 10));
  });
  return prefix + String(max + 1).padStart(pad, "0");
}
function findOrCreate(nome, list, prefix, pad, extra) {
  const trimmed = (nome || "").trim();
  if (!trimmed) return { id: "", list, created: false, nome: "" };
  const found = list.find((x) => x.nome.toLowerCase() === trimmed.toLowerCase());
  if (found) return { id: found.id, list, created: false, nome: found.nome };
  const id = nextId(list, prefix, pad);
  const novo = { id, nome: trimmed, ...extra };
  return { id, list: [...list, novo], created: true, nome: trimmed };
}
function splitNames(s) { return (s || "").split(",").map((n) => n.trim()).filter(Boolean); }
function roleForFormato(formato) {
  if (formato === "Livro") return "Escritor";
  if (formato === "Mangá") return "Mangaká";
  return "Roteirista";
}
function obraKeyFor(it) { return (it.colecaoId || "~") + "||" + it.titulo; }

function usePersistentState(key, initial) {
  const [state, setState] = useState(() => {
    try {
      const saved = window.localStorage.getItem(key);
      return saved ? JSON.parse(saved) : initial;
    } catch {
      return initial;
    }
  });
  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(state));
    } catch {}
  }, [key, state]);
  return [state, setState];
}

function useLookups(itens, editoras, colecoes, leituras, pessoas, personagens) {
  return useMemo(() => {
    const editoraById = Object.fromEntries(editoras.map((e) => [e.id, e]));
    const colecaoById = Object.fromEntries(colecoes.map((c) => [c.id, c]));
    const pessoaById = Object.fromEntries(pessoas.map((p) => [p.id, p]));
    const personagemById = Object.fromEntries(personagens.map((p) => [p.id, p]));
    const leituraByItem = {};
    leituras.forEach((l) => { leituraByItem[l.itemId] = l; });
    const itemsByEditoraNac = {};
    const itemsByColecao = {};
    itens.forEach((it) => {
      (itemsByEditoraNac[it.editoraNacId] ||= []).push(it);
      (itemsByColecao[it.colecaoId] ||= []).push(it);
    });
    return { editoraById, colecaoById, pessoaById, personagemById, leituraByItem, itemsByEditoraNac, itemsByColecao };
  }, [itens, editoras, colecoes, leituras, pessoas, personagens]);
}

function useObras(itens) {
  return useMemo(() => {
    const map = {};
    itens.forEach((it) => {
      const key = obraKeyFor(it);
      if (!map[key]) {
        map[key] = { id: key, titulo: it.titulo, colecaoId: it.colecaoId, genero: it.genero, categoria: it.categoria, itens: [], pessoaIds: new Set(), personagemIds: new Set() };
      }
      map[key].itens.push(it);
      (it.roteiristaIds || []).forEach((id) => map[key].pessoaIds.add(id));
      (it.artistaIds || []).forEach((id) => map[key].pessoaIds.add(id));
      (it.personagemIds || []).forEach((id) => map[key].personagemIds.add(id));
    });
    return Object.values(map).map((o) => ({ ...o, pessoaIds: [...o.pessoaIds], personagemIds: [...o.personagemIds] }));
  }, [itens]);
}
function pessoaFuncaoInObra(obra, pessoaId) {
  for (const it of obra.itens) {
    if ((it.roteiristaIds || []).includes(pessoaId)) return roleForFormato(it.formato);
    if ((it.artistaIds || []).includes(pessoaId)) return "Artista";
  }
  return "";
}

function StatusPill({ lido, onClick }) {
  return (
    <span
      onClick={onClick}
      className="inline-block px-2.5 py-1 text-xs rounded-full border"
      style={{
        ...mono, fontSize: 11,
        borderColor: lido ? T.deep : T.line,
        color: lido ? "#fff" : T.inkSoft,
        backgroundColor: lido ? T.deep : "transparent",
        cursor: onClick ? "pointer" : "default",
      }}
    >
      {lido ? "Lido" : "Não lido"}
    </span>
  );
}
function Card({ children, style, className = "" }) {
  return (
    <div
      className={`border rounded-xl overflow-hidden transition-soft ${className}`}
      style={{ borderColor: T.line, backgroundColor: T.panel, boxShadow: "0 1px 3px rgba(11,37,69,0.07), 0 1px 2px rgba(11,37,69,0.04)", ...style }}
    >
      {children}
    </div>
  );
}
function CardLabel({ children }) {
  return <div className="px-4 py-2.5 border-b text-xs tracking-wide" style={{ ...mono, borderColor: T.line, color: T.inkSoft, fontSize: 12 }}>{children}</div>;
}
function BigStat({ label, value, accent }) {
  return <Card><CardLabel>{label}</CardLabel><div className="px-5 py-6"><div style={{ ...serif, fontSize: 42, lineHeight: 1, color: accent || T.ink }}>{value}</div></div></Card>;
}
function EmptyChart({ msg = "Sem dados suficientes ainda." }) {
  return <div style={{ ...sans, fontSize: 12, color: T.inkSoft, padding: "24px 8px", textAlign: "center" }}>{msg}</div>;
}
function GradientBarChart({ data, dataKey = "value", nameKey = "name", height = 220 }) {
  if (!data.length) return <EmptyChart />;
  return (
    <ResponsiveContainer width="100%" height={height}>
      <BarChart data={data} layout="vertical" margin={{ top: 4, right: 16, bottom: 4, left: 4 }}>
        <CartesianGrid strokeDasharray="2 4" stroke={T.line} horizontal={false} />
        <XAxis type="number" tick={{ fontSize: 11, fill: T.inkSoft, fontFamily: "IBM Plex Mono" }} axisLine={{ stroke: T.line }} tickLine={false} allowDecimals={false} />
        <YAxis type="category" dataKey={nameKey} width={140} tick={{ fontSize: 12, fill: T.ink, fontFamily: "IBM Plex Sans" }} axisLine={{ stroke: T.line }} tickLine={false} />
        <Tooltip cursor={{ fill: T.panelAlt }} contentStyle={{ ...sans, fontSize: 12, border: `1px solid ${T.line}`, borderRadius: 0, backgroundColor: T.panel }} />
        <Bar dataKey={dataKey} radius={[0, 2, 2, 0]}>
          {data.map((_, i) => <Cell key={i} fill={shadeFor(data.length - 1 - i, data.length)} />)}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  );
}
function countBy(list, keyFn) { const m = {}; list.forEach((x) => { const k = keyFn(x); if (!k) return; m[k] = (m[k] || 0) + 1; }); return m; }
function topN(obj, n) { return Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, n).map(([name, value]) => ({ name, value })); }

