function Home({ itens, editoras, colecoes, pessoas, personagens, obras, wishlist, lk, onNavigate }) {
  const lidos = itens.filter((i) => lk.leituraByItem[i.id]).length;
  const modules = [
    { key: "dashboard", label: "Dashboard", desc: "Números gerais do acervo: formatos, editoras, gêneros e leitura.", count: null },
    { key: "acervo", label: "Acervo", desc: "Lista completa, busca, filtros e cadastro de novos itens.", count: itens.length },
    { key: "obras", label: "Obras", desc: "Histórias, criadores, personagens e edições relacionadas.", count: obras.length },
    { key: "editoras", label: "Editoras", desc: "Painel de cada editora: itens, coleções e leitura.", count: editoras.length },
    { key: "colecoes", label: "Coleções", desc: "Painel de cada coleção: completude e itens possuídos.", count: colecoes.length },
    { key: "pessoas", label: "Pessoas", desc: "Roteiristas, escritores, mangakás e artistas.", count: pessoas.length },
    { key: "personagens", label: "Personagens", desc: "Onde cada personagem aparece no acervo.", count: personagens.length },
    { key: "leituras", label: "Leituras", desc: "Histórico de leitura, notas e favoritos.", count: lidos },
    { key: "wishlist", label: "Wishlist", desc: "O que você ainda quer adicionar ao acervo.", count: wishlist.length },
    { key: "grafo", label: "Grafo", desc: "As conexões entre obras, coleções, editoras, pessoas e personagens.", count: null },
    { key: "relatorios", label: "Relatórios", desc: "Análises consolidadas do catálogo e da leitura.", count: null },
  ];
  return (
    <div>
      <div className="mb-10 text-center max-w-2xl mx-auto">
        <div style={{ ...mono, fontSize: 11, color: T.accent, letterSpacing: 1 }}>CATÁLOGO PESSOAL</div>
        <h1 style={{ ...serif, fontSize: 44, color: T.ink, lineHeight: 1.05 }} className="mt-2">{ACERVO_NOME}</h1>
        <div className="flex gap-8 mt-6 flex-wrap justify-center">
          <div><div style={{ ...serif, fontSize: 28, color: T.ink }}>{itens.length}</div><div style={{ ...mono, fontSize: 10, color: T.inkSoft }}>ITENS</div></div>
          <div><div style={{ ...serif, fontSize: 28, color: T.ink }}>{lidos}</div><div style={{ ...mono, fontSize: 10, color: T.inkSoft }}>LIDOS</div></div>
          <div><div style={{ ...serif, fontSize: 28, color: T.ink }}>{editoras.length}</div><div style={{ ...mono, fontSize: 10, color: T.inkSoft }}>EDITORAS</div></div>
          <div><div style={{ ...serif, fontSize: 28, color: T.ink }}>{pessoas.length}</div><div style={{ ...mono, fontSize: 10, color: T.inkSoft }}>PESSOAS</div></div>
        </div>
      </div>
      <p style={{ ...mono, fontSize: 11, color: T.inkSoft, letterSpacing: 0.5 }} className="mb-3 text-center">ESCOLHA O QUE QUER ABRIR</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5 max-w-5xl mx-auto">
        {modules.map((m) => (
          <button key={m.key} onClick={() => onNavigate(m.key)} className="text-left border rounded-xl p-5 flex flex-col justify-between transition-soft" style={{ borderColor: T.line, backgroundColor: T.panel, minHeight: 130, boxShadow: "0 1px 3px rgba(11,37,69,0.05)" }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = T.panelAlt; e.currentTarget.style.boxShadow = "0 6px 18px rgba(11,37,69,0.09)"; e.currentTarget.style.transform = "translateY(-2px)"; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = T.panel; e.currentTarget.style.boxShadow = "0 1px 3px rgba(11,37,69,0.05)"; e.currentTarget.style.transform = "translateY(0)"; }}>
            <div>
              <span style={{ ...serif, fontSize: 19, color: T.ink }}>{m.label}</span>
              <p style={{ ...sans, fontSize: 12.5, color: T.inkSoft }} className="mt-1">{m.desc}</p>
            </div>
            {m.count !== null && <div style={{ ...mono, fontSize: 11, color: T.accent }} className="mt-3">{m.count} {m.count === 1 ? "registro" : "registros"}</div>}
          </button>
        ))}
      </div>
    </div>
  );
}

function Dashboard({ lk, itens, editoras }) {
  const total = itens.length;
  const lidos = itens.filter((i) => lk.leituraByItem[i.id]).length;
  const naoLidos = total - lidos;
  const porFormato = FORMAT_ORDER.map((f) => ({ name: f, value: itens.filter((i) => i.formato === f).length }));
  const porGenero = topN(countBy(itens, (i) => i.genero), 9);
  const porEditora = topN(countBy(itens, (i) => lk.editoraById[i.editoraNacId]?.nome), 8);
  return (
    <div className="space-y-6">
      <div><h1 style={{ ...serif, fontSize: 30, color: T.ink }}>Painel do acervo</h1><p style={{ ...sans, color: T.inkSoft, fontSize: 14 }} className="mt-1">Visão geral da coleção — quadrinhos, mangás, encadernados e livros.</p></div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
        <BigStat label="TOTAL NO ACERVO" value={total} accent={T.ink} />
        <BigStat label="LIDOS" value={lidos} accent={T.deep} />
        <BigStat label="NÃO LIDOS" value={naoLidos} accent={T.accent} />
        <BigStat label="EDITORAS CADASTRADAS" value={editoras.length} accent={T.accent} />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <Card><CardLabel>ITENS POR FORMATO</CardLabel><div className="p-3"><GradientBarChart data={porFormato} height={Math.max(160, porFormato.length * 34)} /></div></Card>
        <Card><CardLabel>LIDOS × NÃO LIDOS</CardLabel><div className="p-3"><GradientBarChart data={[{ name: "Lido", value: lidos }, { name: "Não lido", value: naoLidos }]} height={180} /></div></Card>
        <Card><CardLabel>MAIORES EDITORAS DO ACERVO</CardLabel><div className="p-3"><GradientBarChart data={porEditora} height={260} /></div></Card>
        <Card><CardLabel>DISTRIBUIÇÃO POR GÊNERO</CardLabel><div className="p-3"><GradientBarChart data={porGenero} height={260} /></div></Card>
      </div>
    </div>
  );
}

function FilterBar({ search, setSearch, formato, setFormato, genero, setGenero, status, setStatus, generos }) {
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };
  return (
    <div className="flex flex-wrap gap-2 items-center mb-4">
      <div className="relative flex-1 min-w-[200px]">
        <Search size={14} style={{ position: "absolute", left: 8, top: 9, color: T.inkSoft }} />
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por título..." className="w-full border rounded-md pl-7 pr-2 py-1.5" style={selectStyle} />
      </div>
      <select value={formato} onChange={(e) => setFormato(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todos os formatos</option>{FORMAT_ORDER.map((f) => <option key={f} value={f}>{f}</option>)}
      </select>
      <select value={genero} onChange={(e) => setGenero(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todos os gêneros</option>{generos.map((g) => <option key={g} value={g}>{g}</option>)}
      </select>
      <select value={status} onChange={(e) => setStatus(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Lido e não lido</option><option value="lido">Lido</option><option value="nao">Não lido</option>
      </select>
    </div>
  );
}

function ItemsTable({ items, lk, onEditoraClick, onColecaoClick, onTituloClick, onToggleLido, onEdit }) {
  return (
    <div className="border rounded-xl overflow-auto" style={{ borderColor: T.line, maxHeight: 520 }}>
      <table className="w-full text-sm" style={sans}>
        <thead style={{ backgroundColor: T.panelAlt }}>
          <tr>{["Título", "Formato", "Editora", "Coleção", "Gênero", "Status", ""].map((h) => (
            <th key={h} className="text-left px-3 py-2 border-b sticky top-0" style={{ ...mono, fontSize: 11, borderColor: T.line, backgroundColor: T.panelAlt, color: T.inkSoft }}>{h}</th>
          ))}</tr>
        </thead>
        <tbody>
          {items.map((it) => {
            const ed = lk.editoraById[it.editoraNacId];
            const col = lk.colecaoById[it.colecaoId];
            const lido = !!lk.leituraByItem[it.id];
            return (
              <tr key={it.id} className="border-b hover:bg-black/[0.02]" style={{ borderColor: T.line }}>
                <td className="px-3 py-2" style={{ color: T.ink }}>
                  {onTituloClick ? <button onClick={() => onTituloClick(it)} className="underline decoration-dotted text-left">{it.titulo}</button> : it.titulo}
                </td>
                <td className="px-3 py-2" style={{ color: T.inkSoft }}>{it.formato}</td>
                <td className="px-3 py-2">{ed ? <button onClick={() => onEditoraClick(ed.id)} className="underline decoration-dotted" style={{ color: T.accent }}>{ed.nome}</button> : <span style={{ color: T.inkSoft }}>—</span>}</td>
                <td className="px-3 py-2">{col ? <button onClick={() => onColecaoClick(col.id)} className="underline decoration-dotted" style={{ color: T.deep }}>{col.nome}</button> : <span style={{ color: T.inkSoft }}>—</span>}</td>
                <td className="px-3 py-2" style={{ color: T.inkSoft }}>{it.genero}</td>
                <td className="px-3 py-2"><StatusPill lido={lido} onClick={onToggleLido ? () => onToggleLido(it.id) : undefined} /></td>
                <td className="px-3 py-2">{onEdit && <button onClick={() => onEdit(it.id)} className="underline decoration-dotted text-xs" style={{ ...sans, color: T.inkSoft }}>Editar</button>}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ---------- formulário de cadastro (item + editora + coleção + pessoas + personagens, tudo junto) ----------
const EMPTY_FORM = {
  titulo: "", formato: "Revista", encadernacao: "", editoraNacional: "", editoraInternacional: "",
  colecao: "", categoria: "", genero: "", argumento: "", artista: "", personagens: "",
};
function TextField({ label, value, onChange, listId, list, placeholder }) {
  return (
    <label className="block">
      <span style={{ ...mono, fontSize: 10, color: T.inkSoft }}>{label}</span>
      <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} list={listId} className="w-full border rounded-md mt-1 px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg, color: T.ink }} />
      {list && <datalist id={listId}>{list.map((v) => <option key={v} value={v} />)}</datalist>}
    </label>
  );
}
function NewItemForm({ editoras, colecoes, categorias, generos, pessoas, personagens, onCancel, onSubmit }) {
  const [form, setForm] = useState(EMPTY_FORM);
  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
  return (
    <Card style={{ marginBottom: 16 }}>
      <div className="flex items-center justify-between px-3 py-2 border-b rounded-t-xl" style={{ borderColor: T.line, backgroundColor: T.accentSoft }}>
        <span style={{ ...serif, fontSize: 16, color: T.ink }}>Novo item</span>
        <button onClick={onCancel} style={{ color: T.inkSoft }}><X size={16} /></button>
      </div>
      <div className="p-4 grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="md:col-span-2"><TextField label="TÍTULO *" value={form.titulo} onChange={set("titulo")} placeholder='Ex.: "Superman: Lois e Clark"' /></div>
        <label className="block">
          <span style={{ ...mono, fontSize: 10, color: T.inkSoft }}>FORMATO</span>
          <select value={form.formato} onChange={(e) => set("formato")(e.target.value)} className="w-full border rounded-md mt-1 px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }}>
            {FORMAT_ORDER.map((f) => <option key={f} value={f}>{f}</option>)}
          </select>
        </label>
        <TextField label="EDITORA NACIONAL" value={form.editoraNacional} onChange={set("editoraNacional")} listId="dl-ed-nac" list={editoras.map((e) => e.nome)} placeholder="Existente ou nova" />
        <TextField label="EDITORA INTERNACIONAL" value={form.editoraInternacional} onChange={set("editoraInternacional")} listId="dl-ed-int" list={editoras.map((e) => e.nome)} placeholder="Existente ou nova" />
        <TextField label="COLEÇÃO / SÉRIE" value={form.colecao} onChange={set("colecao")} listId="dl-col" list={colecoes.map((c) => c.nome)} placeholder="Ex.: Coleção Superman" />
        <TextField label={`ARGUMENTO (${roleForFormato(form.formato)})`} value={form.argumento} onChange={set("argumento")} listId="dl-arg" list={pessoas.map((p) => p.nome)} placeholder="Um ou mais nomes, separados por vírgula" />
        <TextField label="ARTISTA" value={form.artista} onChange={set("artista")} listId="dl-art" list={pessoas.map((p) => p.nome)} placeholder="Um ou mais nomes, separados por vírgula" />
        <TextField label="PERSONAGENS" value={form.personagens} onChange={set("personagens")} listId="dl-per" list={personagens.map((p) => p.nome)} placeholder="Um ou mais nomes, separados por vírgula" />
        <TextField label="FORMATO DE ENCADERNAÇÃO" value={form.encadernacao} onChange={set("encadernacao")} placeholder="Capa dura, formatinho..." />
        <TextField label="CATEGORIA" value={form.categoria} onChange={set("categoria")} listId="dl-cat" list={categorias} placeholder="Existente ou nova" />
        <TextField label="GÊNERO" value={form.genero} onChange={set("genero")} listId="dl-gen" list={generos} placeholder="Existente ou novo" />
      </div>
      <div className="flex items-center justify-between px-4 pb-4 flex-wrap gap-2">
        <p style={{ ...sans, fontSize: 11, color: T.inkSoft }} className="max-w-md">Só o título é obrigatório. Editora, coleção, pessoas e personagens que você digitar e ainda não existirem são criados na hora.</p>
        <div className="flex gap-2">
          <button onClick={onCancel} className="px-3 py-1.5 border rounded-md text-sm" style={{ ...sans, borderColor: T.line, color: T.inkSoft }}>Cancelar</button>
          <button disabled={!form.titulo.trim()} onClick={() => onSubmit(form)} className="px-3 py-1.5 rounded-md text-sm flex items-center gap-1" style={{ ...sans, backgroundColor: form.titulo.trim() ? T.deep : T.line, color: form.titulo.trim() ? "#fff" : T.inkSoft }}>
            <Check size={14} /> Adicionar ao acervo
          </button>
        </div>
      </div>
    </Card>
  );
}
function CreationSummary({ summary, onClose }) {
  if (!summary) return null;
  return (
    <div className="px-3 py-3 mb-3 border rounded-lg text-sm" style={{ ...sans, borderColor: T.accent, backgroundColor: T.accentSoft }}>
      <div className="flex items-center justify-between">
        <span style={{ ...serif, fontSize: 15, color: T.ink }}>"{summary.titulo}" adicionado ao acervo</span>
        <button onClick={onClose} style={{ color: T.inkSoft }}><X size={14} /></button>
      </div>
      <p style={{ fontSize: 12, color: T.inkSoft }} className="mt-1">O sistema ramificou os dados para as outras abas automaticamente:</p>
      <ul className="mt-2 space-y-1">
        {summary.entries.map((e, i) => (
          <li key={i} className="flex items-center gap-2" style={{ fontSize: 12.5 }}>
            <span style={{ ...mono, fontSize: 9, padding: "1px 5px", border: `1px solid ${T.line}`, color: T.inkSoft }}>{e.tipo}</span>
            <span style={{ color: T.ink }}>{e.nome}</span>
            <span style={{ ...mono, fontSize: 10, color: e.novo ? T.deep : T.inkSoft }}>{e.novo ? "novo registro criado" : "já existia — reaproveitado"}</span>
          </li>
        ))}
        {summary.entries.length === 0 && <li style={{ fontSize: 12.5, color: T.inkSoft }}>Nenhum dado adicional informado — só o item foi criado.</li>}
      </ul>
    </div>
  );
}

function EditItemModal({ item, editoras, colecoes, categorias, generos, onCancel, onSave }) {
  const [form, setForm] = useState({
    titulo: item.titulo, formato: item.formato, encadernacao: item.encadernacao || "",
    editoraNacional: editoras.find((e) => e.id === item.editoraNacId)?.nome || "",
    editoraInternacional: editoras.find((e) => e.id === item.editoraIntId)?.nome || "",
    colecao: colecoes.find((c) => c.id === item.colecaoId)?.nome || "",
    categoria: item.categoria || "", genero: item.genero || "",
  });
  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
  return (
    <div className="fixed inset-0 flex items-center justify-center p-4" style={{ backgroundColor: "rgba(11,37,69,0.35)", zIndex: 50 }}>
      <div className="w-full max-w-2xl border rounded-xl overflow-hidden" style={{ borderColor: T.line, backgroundColor: T.panel, maxHeight: "90vh", overflowY: "auto" }}>
        <div className="flex items-center justify-between px-4 py-3 border-b rounded-t-xl" style={{ borderColor: T.line, backgroundColor: T.accentSoft }}>
          <span style={{ ...serif, fontSize: 17, color: T.ink }}>Editar item</span>
          <button onClick={onCancel} style={{ color: T.inkSoft }}><X size={18} /></button>
        </div>
        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="md:col-span-2"><TextField label="TÍTULO" value={form.titulo} onChange={set("titulo")} /></div>
          <label className="block">
            <span style={{ ...mono, fontSize: 10, color: T.inkSoft }}>FORMATO</span>
            <select value={form.formato} onChange={(e) => set("formato")(e.target.value)} className="w-full border rounded-md mt-1 px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }}>
              {FORMAT_ORDER.map((f) => <option key={f} value={f}>{f}</option>)}
            </select>
          </label>
          <TextField label="FORMATO DE ENCADERNAÇÃO" value={form.encadernacao} onChange={set("encadernacao")} />
          <TextField label="EDITORA NACIONAL" value={form.editoraNacional} onChange={set("editoraNacional")} listId="dl-edit-ed-nac" list={editoras.map((e) => e.nome)} />
          <TextField label="EDITORA INTERNACIONAL" value={form.editoraInternacional} onChange={set("editoraInternacional")} listId="dl-edit-ed-int" list={editoras.map((e) => e.nome)} />
          <TextField label="COLEÇÃO / SÉRIE" value={form.colecao} onChange={set("colecao")} listId="dl-edit-col" list={colecoes.map((c) => c.nome)} />
          <TextField label="CATEGORIA" value={form.categoria} onChange={set("categoria")} listId="dl-edit-cat" list={categorias} />
          <TextField label="GÊNERO" value={form.genero} onChange={set("genero")} listId="dl-edit-gen" list={generos} />
        </div>
        <div className="flex items-center justify-end gap-2 px-4 pb-4">
          <button onClick={onCancel} className="px-3 py-1.5 border rounded-md text-sm" style={{ ...sans, borderColor: T.line, color: T.inkSoft }}>Cancelar</button>
          <button onClick={() => onSave(form)} disabled={!form.titulo.trim()} className="flex items-center gap-1 px-3 py-1.5 rounded-md text-sm" style={{ ...sans, backgroundColor: form.titulo.trim() ? T.deep : T.line, color: form.titulo.trim() ? "#fff" : T.inkSoft }}>
            <Check size={14} /> Salvar alterações
          </button>
        </div>
      </div>
    </div>
  );
}


function Acervo({ lk, onEditoraClick, onColecaoClick, onObraClick, itens, editoras, colecoes, pessoas, personagens, categorias, onAddItem, onToggleLido, onEdit }) {
  const [search, setSearch] = useState("");
  const [formato, setFormato] = useState("");
  const [genero, setGenero] = useState("");
  const [status, setStatus] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [summary, setSummary] = useState(null);
  const generos = useMemo(() => [...new Set(itens.map((i) => i.genero))].filter(Boolean).sort(), [itens]);
  const filtered = useMemo(() => itens.filter((it) => {
    if (search && !it.titulo.toLowerCase().includes(search.toLowerCase())) return false;
    if (formato && it.formato !== formato) return false;
    if (genero && it.genero !== genero) return false;
    const lido = !!lk.leituraByItem[it.id];
    if (status === "lido" && !lido) return false;
    if (status === "nao" && lido) return false;
    return true;
  }), [search, formato, genero, status, lk, itens]);
  const sorted = useMemo(() => [...filtered].sort((a, b) => a.titulo.localeCompare(b.titulo, "pt-BR")), [filtered]);
  const handleSubmit = (form) => { setSummary(onAddItem(form)); setShowForm(false); };
  return (
    <div>
      <div className="mb-4">
        <div className="flex items-center justify-between">
          <h1 style={{ ...serif, fontSize: 30, color: T.ink }}>Acervo</h1>
          <button onClick={() => setShowForm((s) => !s)} className="flex items-center gap-1 px-3 py-1.5 rounded-md text-sm" style={{ ...sans, backgroundColor: showForm ? T.line : T.ink, color: showForm ? T.inkSoft : "#fff" }}>
            <Plus size={14} /> Novo item
          </button>
        </div>
        <div className="flex justify-end mt-1">
          <span style={{ ...mono, fontSize: 12, color: T.inkSoft }}>{filtered.length} de {itens.length} itens</span>
        </div>
      </div>
      <CreationSummary summary={summary} onClose={() => setSummary(null)} />
      {showForm && <NewItemForm editoras={editoras} colecoes={colecoes} categorias={categorias} generos={generos} pessoas={pessoas} personagens={personagens} onCancel={() => setShowForm(false)} onSubmit={handleSubmit} />}
      <FilterBar {...{ search, setSearch, formato, setFormato, genero, setGenero, status, setStatus, generos }} />
      <ItemsTable items={sorted} lk={lk} onEditoraClick={onEditoraClick} onColecaoClick={onColecaoClick} onTituloClick={(it) => onObraClick(obraKeyFor(it))} onToggleLido={onToggleLido} onEdit={onEdit} />
    </div>
  );
}

function EntityList({ title, entries, onSelect, accent, noun = "item", extra, searchPlaceholder = "Buscar..." }) {
  const [q, setQ] = useState("");
  const filtered = q ? entries.filter((e) => e.nome.toLowerCase().includes(q.toLowerCase())) : entries;
  return (
    <div>
      <div className="mb-4">
        <h1 style={{ ...serif, fontSize: 30, color: T.ink }}>{title}</h1>
        <div className="flex justify-end mt-1">
          <span style={{ ...mono, fontSize: 12, color: T.inkSoft }}>{filtered.length} de {entries.length}</span>
        </div>
      </div>
      {extra}
      <div className="relative mb-4 max-w-sm">
        <Search size={14} style={{ position: "absolute", left: 8, top: 9, color: T.inkSoft }} />
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder={searchPlaceholder} className="w-full border rounded-md pl-7 pr-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.panel, color: T.ink }} />
      </div>
      {filtered.length === 0 ? (
        <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Nada encontrado.</p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((e) => (
            <button key={e.id} onClick={() => onSelect(e.id)} className="text-left border rounded-xl p-3 transition-colors" style={{ borderColor: T.line, backgroundColor: T.panel, boxShadow: "0 1px 3px rgba(11,37,69,0.05)" }}
              onMouseEnter={(ev) => { ev.currentTarget.style.backgroundColor = T.panelAlt; ev.currentTarget.style.boxShadow = "0 6px 18px rgba(11,37,69,0.09)"; ev.currentTarget.style.transform = "translateY(-2px)"; }}
              onMouseLeave={(ev) => { ev.currentTarget.style.backgroundColor = T.panel; ev.currentTarget.style.boxShadow = "0 1px 3px rgba(11,37,69,0.05)"; ev.currentTarget.style.transform = "translateY(0)"; }}>
              {e.id && <div style={{ ...mono, fontSize: 10, color: T.inkSoft }}>{e.id}</div>}
              <div style={{ ...serif, fontSize: 17, color: T.ink }} className="mt-1">{e.nome}</div>
              <div style={{ ...sans, fontSize: 12, color: accent }} className="mt-2">{e.count} {e.count === 1 ? noun : noun + "s"}</div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function EditorasView({ lk, editoras, selected, onSelect, onColecaoClick, onObraClick, onToggleLido, onEdit }) {
  const entries = useMemo(() => editoras.map((e) => ({ ...e, count: (lk.itemsByEditoraNac[e.id] || []).length })).filter((e) => e.count > 0).sort((a, b) => b.count - a.count), [lk, editoras]);
  if (!selected) return <EntityList title="Editoras" entries={entries} onSelect={onSelect} accent={T.accent} searchPlaceholder="Buscar editora..." />;
  const editora = lk.editoraById[selected];
  const items = lk.itemsByEditoraNac[selected] || [];
  const lidos = items.filter((i) => lk.leituraByItem[i.id]).length;
  const colecoesSet = new Set(items.map((i) => i.colecaoId).filter(Boolean));
  const porFormato = FORMAT_ORDER.map((f) => ({ name: f, value: items.filter((i) => i.formato === f).length })).filter((x) => x.value > 0);
  return (
    <div>
      <div style={{ ...mono, fontSize: 11, color: T.inkSoft }}>{editora.id}</div>
      <h1 style={{ ...serif, fontSize: 32, color: T.ink }} className="mb-4">{editora.nome}</h1>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <BigStat label="ITENS NO ACERVO" value={items.length} accent={T.ink} />
        <BigStat label="COLEÇÕES" value={colecoesSet.size} accent={T.accent} />
        <BigStat label="LIDOS" value={lidos} accent={T.deep} />
        <BigStat label="NÃO LIDOS" value={items.length - lidos} accent={T.accent} />
      </div>
      <Card style={{ marginBottom: 24 }}><CardLabel>DISTRIBUIÇÃO POR FORMATO</CardLabel><div className="p-3"><GradientBarChart data={porFormato} height={Math.max(100, porFormato.length * 40)} /></div></Card>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Itens desta editora</h2>
      <ItemsTable items={items} lk={lk} onEditoraClick={() => {}} onColecaoClick={onColecaoClick} onTituloClick={(it) => onObraClick(obraKeyFor(it))} onToggleLido={onToggleLido} onEdit={onEdit} />
    </div>
  );
}

function ColecoesView({ lk, colecoes, itens, editoras, selected, onSelect, onEditoraClick, onObraClick, onToggleLido, onEdit }) {
  const [editoraF, setEditoraF] = useState("");
  const [statusF, setStatusF] = useState("");
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };

  const entries = useMemo(() => {
    return colecoes
      .map((c) => {
        const its = lk.itemsByColecao[c.id] || [];
        const lidos = its.filter((i) => lk.leituraByItem[i.id]).length;
        return { ...c, count: its.length, lidos, naoLidos: its.length - lidos };
      })
      .filter((c) => c.count > 0)
      .filter((c) => !editoraF || c.editoraId === editoraF)
      .filter((c) => !statusF || (statusF === "completa" ? c.naoLidos === 0 : c.naoLidos > 0))
      .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));
  }, [lk, colecoes, editoraF, statusF]);

  const filtros = (
    <div className="flex flex-wrap gap-2 mb-4">
      <select value={editoraF} onChange={(e) => setEditoraF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todas as editoras</option>
        {editoras.map((e) => <option key={e.id} value={e.id}>{e.nome}</option>)}
      </select>
      <select value={statusF} onChange={(e) => setStatusF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Completas e com pendências</option>
        <option value="completa">100% lidas</option>
        <option value="pendente">Com itens não lidos</option>
      </select>
    </div>
  );

  if (!selected) return <EntityList title="Coleções" entries={entries} onSelect={onSelect} accent={T.deep} searchPlaceholder="Buscar coleção..." extra={filtros} />;
  const colecao = lk.colecaoById[selected];
  const items = [...(lk.itemsByColecao[selected] || [])].sort((a, b) => a.titulo.localeCompare(b.titulo, "pt-BR"));
  const editora = lk.editoraById[colecao.editoraId];
  const lidos = items.filter((i) => lk.leituraByItem[i.id]).length;
  return (
    <div>
      <div style={{ ...mono, fontSize: 11, color: T.inkSoft }}>{colecao.id}</div>
      <h1 style={{ ...serif, fontSize: 32, color: T.ink }}>{colecao.nome}</h1>
      {editora && <button onClick={() => onEditoraClick(editora.id)} className="underline decoration-dotted text-sm mb-4 inline-block" style={{ color: T.accent, ...sans }}>{editora.nome}</button>}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 my-6">
        <BigStat label="ITENS POSSUÍDOS" value={items.length} accent={T.ink} />
        <BigStat label="LIDOS" value={lidos} accent={T.deep} />
        <BigStat label="NÃO LIDOS" value={items.length - lidos} accent={T.accent} />
      </div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Itens da coleção</h2>
      <ItemsTable items={items} lk={lk} onEditoraClick={onEditoraClick} onColecaoClick={() => {}} onTituloClick={(it) => onObraClick(obraKeyFor(it))} onToggleLido={onToggleLido} onEdit={onEdit} />
    </div>
  );
}

function ObrasView({ obras, lk, editoras, selected, onSelect, onEditoraClick, onColecaoClick, onPessoaClick, onPersonagemClick, onToggleLido, onEdit }) {
  const [generoF, setGeneroF] = useState("");
  const [categoriaF, setCategoriaF] = useState("");
  const [editoraF, setEditoraF] = useState("");
  const [statusF, setStatusF] = useState("");
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };

  const generos = useMemo(() => [...new Set(obras.map((o) => o.genero))].filter(Boolean).sort(), [obras]);
  const categorias = useMemo(() => [...new Set(obras.map((o) => o.categoria))].filter(Boolean).sort(), [obras]);

  function obraEditoraId(o) {
    const colecao = lk.colecaoById[o.colecaoId];
    return colecao ? colecao.editoraId : o.itens[0]?.editoraNacId;
  }

  const entries = useMemo(() => {
    return obras
      .filter((o) => !generoF || o.genero === generoF)
      .filter((o) => !categoriaF || o.categoria === categoriaF)
      .filter((o) => !editoraF || obraEditoraId(o) === editoraF)
      .filter((o) => {
        if (!statusF) return true;
        const algumLido = o.itens.some((i) => lk.leituraByItem[i.id]);
        return statusF === "lido" ? algumLido : !algumLido;
      })
      .map((o) => ({ id: o.id, nome: o.titulo, count: o.itens.length }))
      .sort((a, b) => a.nome.localeCompare(b.nome));
  }, [obras, generoF, categoriaF, editoraF, statusF, lk]);

  const filtros = (
    <div className="flex flex-wrap gap-2 mb-4">
      <select value={generoF} onChange={(e) => setGeneroF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todos os gêneros</option>{generos.map((g) => <option key={g} value={g}>{g}</option>)}
      </select>
      <select value={categoriaF} onChange={(e) => setCategoriaF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todas as categorias</option>{categorias.map((c) => <option key={c} value={c}>{c}</option>)}
      </select>
      <select value={editoraF} onChange={(e) => setEditoraF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Todas as editoras</option>{editoras.map((e) => <option key={e.id} value={e.id}>{e.nome}</option>)}
      </select>
      <select value={statusF} onChange={(e) => setStatusF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
        <option value="">Lidas e não lidas</option>
        <option value="lido">Com alguma edição lida</option>
        <option value="nao">Nenhuma edição lida</option>
      </select>
    </div>
  );

  if (!selected) return <EntityList title="Obras" entries={entries} onSelect={onSelect} accent={T.accent} noun="edição" searchPlaceholder="Buscar obra..." extra={filtros} />;
  const obra = obras.find((o) => o.id === selected);
  if (!obra) return <EntityList title="Obras" entries={entries} onSelect={onSelect} accent={T.accent} noun="edição" searchPlaceholder="Buscar obra..." extra={filtros} />;
  const colecao = lk.colecaoById[obra.colecaoId];
  const editora = colecao ? lk.editoraById[colecao.editoraId] : lk.editoraById[obra.itens[0]?.editoraNacId];
  return (
    <div>
      <h1 style={{ ...serif, fontSize: 32, color: T.ink }}>{obra.titulo}</h1>
      <div className="flex gap-3 mt-1 flex-wrap">
        {colecao && <button onClick={() => onColecaoClick(colecao.id)} className="underline decoration-dotted text-sm" style={{ color: T.deep, ...sans }}>{colecao.nome}</button>}
        {editora && <button onClick={() => onEditoraClick(editora.id)} className="underline decoration-dotted text-sm" style={{ color: T.accent, ...sans }}>{editora.nome}</button>}
      </div>
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 my-6">
        <BigStat label="EDIÇÕES NO ACERVO" value={obra.itens.length} accent={T.ink} />
        <BigStat label="CRIADORES" value={obra.pessoaIds.length} accent={T.accent} />
        <BigStat label="PERSONAGENS" value={obra.personagemIds.length} accent={T.deep} />
      </div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Criadores</h2>
      <div className="mb-6 flex flex-wrap">
        {obra.pessoaIds.length === 0 && <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Nenhum criador cadastrado para esta obra ainda.</p>}
        {obra.pessoaIds.map((id) => {
          const p = lk.pessoaById[id];
          const funcao = pessoaFuncaoInObra(obra, id);
          return (
            <button key={id} onClick={() => onPessoaClick(id)} className="text-left border rounded-lg px-2 py-1 mr-2 mb-2 inline-flex items-center gap-2" style={{ borderColor: T.line, backgroundColor: T.panel }}>
              <span style={{ ...serif, fontSize: 13, color: T.ink }}>{p?.nome}</span>
              {funcao && <span style={{ ...mono, fontSize: 9, color: T.inkSoft }}>{funcao.toUpperCase()}</span>}
            </button>
          );
        })}
      </div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Personagens</h2>
      <div className="mb-6 flex flex-wrap">
        {obra.personagemIds.length === 0 && <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Nenhum personagem ligado a esta obra ainda.</p>}
        {obra.personagemIds.map((id) => {
          const p = lk.personagemById[id];
          return <button key={id} onClick={() => onPersonagemClick(id)} className="text-left border rounded-lg px-2 py-1 mr-2 mb-2" style={{ borderColor: T.line, backgroundColor: T.panel, ...serif, fontSize: 13, color: T.ink }}>{p?.nome}</button>;
        })}
      </div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Edições no acervo</h2>
      <ItemsTable items={obra.itens} lk={lk} onEditoraClick={onEditoraClick} onColecaoClick={onColecaoClick} onToggleLido={onToggleLido} onEdit={onEdit} />
    </div>
  );
}

function LinkItemWidget({ itens, alreadyLinkedIds = [], onLink, label = "Vincular a um item existente" }) {
  const [itemId, setItemId] = useState("");
  const options = useMemo(() => itens.filter((it) => !alreadyLinkedIds.includes(it.id)).sort((a, b) => a.titulo.localeCompare(b.titulo)), [itens, alreadyLinkedIds]);
  const link = () => {
    if (!itemId) return;
    onLink(itemId);
    setItemId("");
  };
  return (
    <div className="flex gap-2 flex-wrap">
      <select value={itemId} onChange={(e) => setItemId(e.target.value)} className="border rounded-md px-2 py-1.5 flex-1 min-w-[220px]" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg, color: T.ink }}>
        <option value="">{label}</option>
        {options.map((it) => <option key={it.id} value={it.id}>{it.titulo}</option>)}
      </select>
      <button onClick={link} disabled={!itemId} className="flex items-center gap-1 px-3 py-1.5 rounded-md text-sm" style={{ ...sans, backgroundColor: itemId ? T.ink : T.line, color: itemId ? "#fff" : T.inkSoft }}><Plus size={14} /> Vincular</button>
    </div>
  );
}

function PessoasView({ pessoas, itens, lk, selected, onSelect, onObraClick, onToggleLido, onEdit }) {
  const entries = useMemo(() => pessoas.map((p) => ({ id: p.id, nome: p.nome, count: itens.filter((it) => (it.roteiristaIds || []).includes(p.id) || (it.artistaIds || []).includes(p.id)).length })).filter((p) => p.count > 0).sort((a, b) => b.count - a.count), [pessoas, itens]);
  if (!selected) return <EntityList title="Pessoas" entries={entries} onSelect={onSelect} accent={T.deep} noun="item" searchPlaceholder="Buscar pessoa..." />;
  const pessoa = pessoas.find((p) => p.id === selected);
  if (!pessoa) return <EntityList title="Pessoas" entries={entries} onSelect={onSelect} accent={T.deep} searchPlaceholder="Buscar pessoa..." />;
  const items = itens.filter((it) => (it.roteiristaIds || []).includes(selected) || (it.artistaIds || []).includes(selected));
  return (
    <div>
      <div style={{ ...mono, fontSize: 11, color: T.inkSoft }}>{pessoa.id}</div>
      <h1 style={{ ...serif, fontSize: 32, color: T.ink }} className="mb-6">{pessoa.nome}</h1>
      <div className="grid grid-cols-2 gap-4 mb-6"><BigStat label="ITENS RELACIONADOS" value={items.length} accent={T.ink} /></div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Participações</h2>
      <ItemsTable items={items} lk={lk} onEditoraClick={() => {}} onColecaoClick={() => {}} onTituloClick={(it) => onObraClick(obraKeyFor(it))} onToggleLido={onToggleLido} onEdit={onEdit} />
    </div>
  );
}

function PersonagensView({ personagens, setPersonagens, itens, setItens, lk, selected, onSelect, onObraClick, onToggleLido, onEdit }) {
  const [novo, setNovo] = useState("");
  const [novoItemId, setNovoItemId] = useState("");
  const linkItemToPersonagem = (itemId, personagemId) => {
    setItens((prev) => prev.map((it) => it.id === itemId ? { ...it, personagemIds: [...(it.personagemIds || []), personagemId] } : it));
  };
  const add = () => {
    if (!novo.trim()) return;
    const r = findOrCreate(novo, personagens, "PER-", 4, {});
    const list = r.created ? r.list : personagens;
    if (r.created) setPersonagens(list);
    if (novoItemId) linkItemToPersonagem(novoItemId, r.id);
    setNovo(""); setNovoItemId("");
  };
  const entries = useMemo(() => personagens.map((p) => ({ id: p.id, nome: p.nome, count: itens.filter((it) => (it.personagemIds || []).includes(p.id)).length })).sort((a, b) => b.count - a.count), [personagens, itens]);
  const itensOrdenados = useMemo(() => [...itens].sort((a, b) => a.titulo.localeCompare(b.titulo)), [itens]);

  if (!selected) {
    const addForm = (
      <div className="border rounded-xl p-3 mb-4 max-w-xl" style={{ borderColor: T.line, backgroundColor: T.panelAlt }}>
        <div style={{ ...mono, fontSize: 10, color: T.inkSoft }} className="mb-2">NOVO PERSONAGEM</div>
        <div className="flex gap-2 flex-wrap">
          <input value={novo} onChange={(e) => setNovo(e.target.value)} placeholder="Nome do personagem" className="flex-1 border rounded-md px-2 py-1.5 min-w-[160px]" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }} />
          <select value={novoItemId} onChange={(e) => setNovoItemId(e.target.value)} className="border rounded-md px-2 py-1.5 flex-1 min-w-[200px]" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }}>
            <option value="">Vincular a um item (opcional)</option>
            {itensOrdenados.map((it) => <option key={it.id} value={it.id}>{it.titulo}</option>)}
          </select>
          <button onClick={add} disabled={!novo.trim()} className="flex items-center gap-1 px-3 py-1.5 rounded-md text-sm" style={{ ...sans, backgroundColor: novo.trim() ? T.ink : T.line, color: novo.trim() ? "#fff" : T.inkSoft }}><Plus size={14} /> Adicionar</button>
        </div>
      </div>
    );
    return <EntityList title="Personagens" entries={entries} onSelect={onSelect} accent={T.accent} noun="aparição" extra={addForm} searchPlaceholder="Buscar personagem..." />;
  }
  const personagem = personagens.find((p) => p.id === selected);
  if (!personagem) return <EntityList title="Personagens" entries={entries} onSelect={onSelect} accent={T.accent} searchPlaceholder="Buscar personagem..." />;
  const items = itens.filter((it) => (it.personagemIds || []).includes(selected));
  return (
    <div>
      <div style={{ ...mono, fontSize: 11, color: T.inkSoft }}>{personagem.id}</div>
      <h1 style={{ ...serif, fontSize: 32, color: T.ink }} className="mb-6">{personagem.nome}</h1>
      <div className="grid grid-cols-2 gap-4 mb-6"><BigStat label="APARIÇÕES NO ACERVO" value={items.length} accent={T.ink} /></div>
      <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Vincular a um título já cadastrado</h2>
      <div className="mb-6"><LinkItemWidget itens={itens} alreadyLinkedIds={items.map((i) => i.id)} onLink={(itemId) => linkItemToPersonagem(itemId, selected)} /></div>
      {items.length === 0 ? (
        <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Ainda não ligado a nenhum item.</p>
      ) : (
        <>
          <h2 style={{ ...serif, fontSize: 18, color: T.ink }} className="mb-2">Aparece em</h2>
          <ItemsTable items={items} lk={lk} onEditoraClick={() => {}} onColecaoClick={() => {}} onTituloClick={(it) => onObraClick(obraKeyFor(it))} onToggleLido={onToggleLido} onEdit={onEdit} />
        </>
      )}
    </div>
  );
}

function LeiturasView({ lk, itens, leituras, onToggleLido, onObraClick }) {
  const [search, setSearch] = useState("");
  const [favorito, setFavorito] = useState("");
  const [releitura, setReleitura] = useState("");
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };
  const rows = useMemo(() => leituras
    .map((l) => { const item = itens.find((i) => i.id === l.itemId); return { ...l, titulo: item?.titulo || "—", item }; })
    .filter((r) => !search || r.titulo.toLowerCase().includes(search.toLowerCase()))
    .filter((r) => !favorito || r.favorito === favorito)
    .filter((r) => !releitura || r.releitura === releitura)
    .sort((a, b) => a.titulo.localeCompare(b.titulo, "pt-BR")), [itens, leituras, search, favorito, releitura]);
  return (
    <div>
      <h1 style={{ ...serif, fontSize: 30, color: T.ink }} className="mb-1">Leituras</h1>
      <p style={{ ...sans, color: T.inkSoft, fontSize: 13 }} className="mb-4">{rows.length} de {leituras.length} registros de leitura. Clique no status pra marcar como não lido. Nota, favorito e resenha ficam vazios até você preencher.</p>
      <div className="flex flex-wrap gap-2 mb-4">
        <div className="relative flex-1 min-w-[200px]">
          <Search size={14} style={{ position: "absolute", left: 8, top: 9, color: T.inkSoft }} />
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar por título..." className="w-full border rounded-md pl-7 pr-2 py-1.5" style={selectStyle} />
        </div>
        <select value={favorito} onChange={(e) => setFavorito(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
          <option value="">Favorito: todos</option><option value="Sim">Favorito</option><option value="Não">Não favorito</option>
        </select>
        <select value={releitura} onChange={(e) => setReleitura(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}>
          <option value="">Releitura: todas</option><option value="Sim">Releitura</option><option value="Não">Primeira leitura</option>
        </select>
      </div>
      <div className="border rounded-xl overflow-auto" style={{ borderColor: T.line, maxHeight: 520 }}>
        <table className="w-full text-sm" style={sans}>
          <thead style={{ backgroundColor: T.panelAlt }}><tr>{["Título", "Status", "Nota", "Favorito", "Releitura"].map((h) => <th key={h} className="text-left px-3 py-2 border-b sticky top-0" style={{ ...mono, fontSize: 11, borderColor: T.line, backgroundColor: T.panelAlt, color: T.inkSoft }}>{h}</th>)}</tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id} className="border-b" style={{ borderColor: T.line }}>
                <td className="px-3 py-2" style={{ color: T.ink }}>
                  {r.item ? <button onClick={() => onObraClick(obraKeyFor(r.item))} className="underline decoration-dotted text-left">{r.titulo}</button> : r.titulo}
                </td>
                <td className="px-3 py-2"><StatusPill lido={r.status === "Lido"} onClick={onToggleLido ? () => onToggleLido(r.itemId) : undefined} /></td>
                <td className="px-3 py-2" style={{ color: T.inkSoft }}>{r.nota || "—"}</td>
                <td className="px-3 py-2" style={{ color: T.inkSoft }}>{r.favorito || "—"}</td>
                <td className="px-3 py-2" style={{ color: T.inkSoft }}>{r.releitura || "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function WishlistView({ wishlist, setWishlist }) {
  const [texto, setTexto] = useState("");
  const [formato, setFormato] = useState("");
  const [prioridade, setPrioridade] = useState("Média");
  const [obs, setObs] = useState("");
  const prioColor = { Alta: T.deep, "Média": T.accent, Baixa: T.line };
  const add = () => {
    if (!texto.trim()) return;
    const novo = { id: nextId(wishlist, "WISH-", 4), titulo: texto.trim(), formato, prioridade, obs: obs.trim() };
    setWishlist([novo, ...wishlist]);
    setTexto(""); setObs(""); setFormato(""); setPrioridade("Média");
  };
  const remove = (id) => setWishlist(wishlist.filter((w) => w.id !== id));
  return (
    <div>
      <h1 style={{ ...serif, fontSize: 30, color: T.ink }} className="mb-1">Wishlist</h1>
      <p style={{ ...sans, color: T.inkSoft, fontSize: 13 }} className="mb-4">O que você ainda quer colocar no acervo. Sem controle de preço ou compra — só a lista.</p>
      <Card style={{ marginBottom: 20 }}>
        <div className="p-4 space-y-3">
          <label className="block">
            <span style={{ ...mono, fontSize: 10, color: T.inkSoft }}>O QUE VOCÊ QUER ADICIONAR AO ACERVO?</span>
            <input value={texto} onChange={(e) => setTexto(e.target.value)} onKeyDown={(e) => e.key === "Enter" && add()} placeholder='Ex.: "Sandman, Edição Definitiva vol. 2"'
              className="w-full border rounded-md mt-1 px-2 py-2" style={{ ...sans, fontSize: 14, borderColor: T.line, backgroundColor: T.bg, color: T.ink }} />
          </label>
          <div className="flex gap-3 flex-wrap">
            <select value={formato} onChange={(e) => setFormato(e.target.value)} className="border rounded-md px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }}>
              <option value="">Formato (opcional)</option>{FORMAT_ORDER.map((f) => <option key={f} value={f}>{f}</option>)}
            </select>
            <select value={prioridade} onChange={(e) => setPrioridade(e.target.value)} className="border rounded-md px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg }}>
              <option>Alta</option><option>Média</option><option>Baixa</option>
            </select>
          </div>
          <textarea value={obs} onChange={(e) => setObs(e.target.value)} placeholder="Observações (opcional)" rows={2} className="w-full border rounded-md px-2 py-1.5" style={{ ...sans, fontSize: 13, borderColor: T.line, backgroundColor: T.bg, color: T.ink }} />
          <div className="flex justify-end"><button onClick={add} disabled={!texto.trim()} className="flex items-center gap-1 px-3 py-1.5 rounded-md text-sm" style={{ ...sans, backgroundColor: texto.trim() ? T.ink : T.line, color: texto.trim() ? "#fff" : T.inkSoft }}><Plus size={14} /> Adicionar à wishlist</button></div>
        </div>
      </Card>
      {wishlist.length === 0 ? <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Nada na wishlist ainda.</p> : (
        <div className="space-y-2">
          {wishlist.map((w) => (
            <div key={w.id} className="border rounded-lg p-3 flex items-center justify-between gap-3" style={{ borderColor: T.line, backgroundColor: T.panel }}>
              <div>
                <div style={{ ...serif, fontSize: 16, color: T.ink }}>{w.titulo}</div>
                <div style={{ ...sans, fontSize: 12, color: T.inkSoft }} className="mt-0.5">{[w.formato, w.obs].filter(Boolean).join(" — ") || "\u00A0"}</div>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span style={{ ...mono, fontSize: 10, padding: "2px 6px", color: w.prioridade === "Baixa" ? T.inkSoft : "#fff", backgroundColor: prioColor[w.prioridade] }}>{w.prioridade.toUpperCase()}</span>
                <button onClick={() => remove(w.id)} style={{ color: T.inkSoft }}><X size={14} /></button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function RelatoriosView({ itens, editoras, colecoes, personagens, lk }) {
  const [formato, setFormato] = useState("");
  const [editoraF, setEditoraF] = useState("");
  const [colecaoF, setColecaoF] = useState("");
  const [genero, setGenero] = useState("");
  const [status, setStatus] = useState("");
  const generos = useMemo(() => [...new Set(itens.map((i) => i.genero))].filter(Boolean).sort(), [itens]);
  const filtered = useMemo(() => itens.filter((it) => {
    if (formato && it.formato !== formato) return false;
    if (editoraF && it.editoraNacId !== editoraF) return false;
    if (colecaoF && it.colecaoId !== colecaoF) return false;
    if (genero && it.genero !== genero) return false;
    const lido = !!lk.leituraByItem[it.id];
    if (status === "lido" && !lido) return false;
    if (status === "nao" && lido) return false;
    return true;
  }), [itens, formato, editoraF, colecaoF, genero, status, lk]);
  const lidos = filtered.filter((it) => lk.leituraByItem[it.id]).length;
  const porFormato = FORMAT_ORDER.map((f) => ({ name: f, value: filtered.filter((i) => i.formato === f).length }));
  const porEditora = topN(countBy(filtered, (i) => lk.editoraById[i.editoraNacId]?.nome), 10);
  const porColecao = topN(countBy(filtered, (i) => lk.colecaoById[i.colecaoId]?.nome), 10);
  const porGenero = topN(countBy(filtered, (i) => i.genero), 10);
  const porCategoria = topN(countBy(filtered, (i) => i.categoria), 10);
  const pessoaCount = {};
  filtered.forEach((it) => {
    (it.roteiristaIds || []).forEach((id) => { pessoaCount[id] = (pessoaCount[id] || 0) + 1; });
    (it.artistaIds || []).forEach((id) => { pessoaCount[id] = (pessoaCount[id] || 0) + 1; });
  });
  const porPessoa = topN(Object.fromEntries(Object.entries(pessoaCount).map(([id, c]) => [lk.pessoaById[id]?.nome || id, c])), 10);
  const personagemCount = {};
  filtered.forEach((it) => { (it.personagemIds || []).forEach((id) => { personagemCount[id] = (personagemCount[id] || 0) + 1; }); });
  const porPersonagem = topN(Object.fromEntries(Object.entries(personagemCount).map(([id, c]) => [lk.personagemById[id]?.nome || id, c])), 10);
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };
  return (
    <div>
      <h1 style={{ ...serif, fontSize: 30, color: T.ink }} className="mb-1">Relatórios</h1>
      <p style={{ ...sans, color: T.inkSoft, fontSize: 13 }} className="mb-4">Filtre por qualquer combinação abaixo — todos os números e gráficos se ajustam.</p>
      <div className="flex flex-wrap gap-2 mb-6">
        <select value={formato} onChange={(e) => setFormato(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}><option value="">Todos os formatos</option>{FORMAT_ORDER.map((f) => <option key={f} value={f}>{f}</option>)}</select>
        <select value={editoraF} onChange={(e) => setEditoraF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}><option value="">Todas as editoras</option>{editoras.map((e) => <option key={e.id} value={e.id}>{e.nome}</option>)}</select>
        <select value={colecaoF} onChange={(e) => setColecaoF(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}><option value="">Todas as coleções</option>{colecoes.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
        <select value={genero} onChange={(e) => setGenero(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}><option value="">Todos os gêneros</option>{generos.map((g) => <option key={g} value={g}>{g}</option>)}</select>
        <select value={status} onChange={(e) => setStatus(e.target.value)} className="border rounded-md px-2 py-1.5" style={selectStyle}><option value="">Lido e não lido</option><option value="lido">Lido</option><option value="nao">Não lido</option></select>
      </div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <BigStat label="ITENS NO FILTRO" value={filtered.length} accent={T.ink} />
        <BigStat label="LIDOS" value={lidos} accent={T.deep} />
        <BigStat label="NÃO LIDOS" value={filtered.length - lidos} accent={T.accent} />
        <BigStat label="EDITORAS ENVOLVIDAS" value={new Set(filtered.map((i) => i.editoraNacId).filter(Boolean)).size} accent={T.accent} />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        <Card><CardLabel>ITENS POR FORMATO</CardLabel><div className="p-3"><GradientBarChart data={porFormato} height={Math.max(160, porFormato.length * 34)} /></div></Card>
        <Card><CardLabel>LIDOS × NÃO LIDOS</CardLabel><div className="p-3"><GradientBarChart data={[{ name: "Lido", value: lidos }, { name: "Não lido", value: filtered.length - lidos }]} height={160} /></div></Card>
        <Card><CardLabel>ITENS POR EDITORA</CardLabel><div className="p-3"><GradientBarChart data={porEditora} height={260} /></div></Card>
        <Card><CardLabel>ITENS POR COLEÇÃO</CardLabel><div className="p-3"><GradientBarChart data={porColecao} height={260} /></div></Card>
        <Card><CardLabel>ITENS POR GÊNERO</CardLabel><div className="p-3"><GradientBarChart data={porGenero} height={240} /></div></Card>
        <Card><CardLabel>ITENS POR CATEGORIA</CardLabel><div className="p-3"><GradientBarChart data={porCategoria} height={200} /></div></Card>
        <Card><CardLabel>CRIADORES MAIS PRESENTES</CardLabel><div className="p-3"><GradientBarChart data={porPessoa} height={260} /></div></Card>
        <Card><CardLabel>PERSONAGENS MAIS PRESENTES</CardLabel><div className="p-3">{personagens.length === 0 ? <EmptyChart msg="Nenhum personagem cadastrado ainda." /> : <GradientBarChart data={porPersonagem} height={200} />}</div></Card>
      </div>
    </div>
  );
}

function GrafoView({ obras, editoras, colecoes, lk }) {
  const [editoraF, setEditoraF] = useState("");
  const [colecaoF, setColecaoF] = useState("");
  const [highlighted, setHighlighted] = useState(null);
  const selectStyle = { ...sans, fontSize: 13, borderColor: T.line, color: T.ink, backgroundColor: T.panel };
  const GRAPH_COLORS = { editora: "#378ADD", colecao: "#1D9E75", obra: "#7F77DD", pessoa: "#D85A30", personagem: "#BA7517" };

  const colecoesDaEditora = useMemo(() => colecoes.filter((c) => !editoraF || c.editoraId === editoraF), [colecoes, editoraF]);

  const scopeObras = useMemo(() => {
    if (colecaoF) return obras.filter((o) => o.colecaoId === colecaoF);
    if (editoraF) {
      const colIds = new Set(colecoesDaEditora.map((c) => c.id));
      return obras.filter((o) => colIds.has(o.colecaoId));
    }
    return [];
  }, [obras, editoraF, colecaoF, colecoesDaEditora]);

  const graph = useMemo(() => {
    if (scopeObras.length === 0 || scopeObras.length > 30) return null;
    const colecaoIds = [...new Set(scopeObras.map((o) => o.colecaoId).filter(Boolean))];
    const editoraIds = [...new Set(colecaoIds.map((id) => lk.colecaoById[id]?.editoraId).filter(Boolean))];
    const pessoaIds = [...new Set(scopeObras.flatMap((o) => o.pessoaIds))];
    const personagemIds = [...new Set(scopeObras.flatMap((o) => o.personagemIds))];
    const nodes = [];
    const W = 680;
    function layoutRow(ids, y, type) {
      const n = ids.length;
      ids.forEach((id, i) => {
        const x = n === 1 ? W / 2 : 60 + (i * (W - 120)) / (n - 1);
        nodes.push({ id: `${type}-${id}`, rawId: id, type, x, y });
      });
    }
    layoutRow(editoraIds, 50, "editora");
    layoutRow(colecaoIds, 140, "colecao");
    layoutRow(scopeObras.map((o) => o.id), 230, "obra");
    layoutRow(pessoaIds, 320, "pessoa");
    layoutRow(personagemIds, 400, "personagem");
    const byKey = Object.fromEntries(nodes.map((n) => [n.id, n]));
    const edges = [];
    colecaoIds.forEach((cid) => {
      const col = lk.colecaoById[cid];
      if (col?.editoraId && byKey[`editora-${col.editoraId}`]) edges.push(["editora-" + col.editoraId, "colecao-" + cid]);
    });
    scopeObras.forEach((o) => {
      if (o.colecaoId && byKey["colecao-" + o.colecaoId]) edges.push(["colecao-" + o.colecaoId, "obra-" + o.id]);
      (o.pessoaIds || []).forEach((pid) => edges.push(["obra-" + o.id, "pessoa-" + pid]));
      (o.personagemIds || []).forEach((pid) => edges.push(["obra-" + o.id, "personagem-" + pid]));
    });
    const labelFor = (n) => {
      if (n.type === "editora") return lk.editoraById[n.rawId]?.nome || "?";
      if (n.type === "colecao") return lk.colecaoById[n.rawId]?.nome || "?";
      if (n.type === "obra") return scopeObras.find((o) => o.id === n.rawId)?.titulo || "?";
      if (n.type === "pessoa") return lk.pessoaById[n.rawId]?.nome || "?";
      return lk.personagemById[n.rawId]?.nome || "?";
    };
    const withLabels = nodes.map((n) => ({ ...n, label: labelFor(n) }));
    const height = Math.max(...withLabels.map((n) => n.y), 0) + 40;
    return { nodes: withLabels, edges, height };
  }, [scopeObras, lk]);

  const connected = useMemo(() => {
    if (!highlighted || !graph) return null;
    const set = new Set([highlighted]);
    graph.edges.forEach(([a, b]) => { if (a === highlighted) set.add(b); if (b === highlighted) set.add(a); });
    return set;
  }, [highlighted, graph]);

  return (
    <div>
      <div className="mb-4"><h1 style={{ ...serif, fontSize: 30, color: T.ink }}>Grafo</h1></div>
      <p style={{ ...sans, fontSize: 13, color: T.inkSoft }} className="mb-4">Escolha uma editora (e, se quiser, uma coleção) pra ver como as obras se conectam a criadores e personagens.</p>
      <div className="flex flex-wrap gap-2 mb-4">
        <select value={editoraF} onChange={(e) => { setEditoraF(e.target.value); setColecaoF(""); setHighlighted(null); }} className="border rounded-md px-2 py-1.5" style={selectStyle}>
          <option value="">Escolha uma editora</option>
          {editoras.map((e) => <option key={e.id} value={e.id}>{e.nome}</option>)}
        </select>
        <select value={colecaoF} onChange={(e) => { setColecaoF(e.target.value); setHighlighted(null); }} disabled={!editoraF} className="border rounded-md px-2 py-1.5" style={selectStyle}>
          <option value="">Todas as coleções desta editora</option>
          {colecoesDaEditora.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
        </select>
      </div>
      {!editoraF && <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Selecione uma editora pra começar.</p>}
      {editoraF && scopeObras.length === 0 && <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>Nenhum item encontrado nesse filtro.</p>}
      {editoraF && scopeObras.length > 30 && <p style={{ ...sans, fontSize: 13, color: T.inkSoft }}>{scopeObras.length} itens é demais pra mostrar de uma vez — escolha uma coleção específica ao lado.</p>}
      {graph && (
        <Card>
          <div className="p-3">
            <svg width="100%" viewBox={`0 0 680 ${graph.height}`}>
              {graph.edges.map(([a, b], i) => {
                const A = graph.nodes.find((n) => n.id === a);
                const B = graph.nodes.find((n) => n.id === b);
                if (!A || !B) return null;
                const on = !highlighted || a === highlighted || b === highlighted;
                return <line key={i} x1={A.x} y1={A.y} x2={B.x} y2={B.y} stroke={T.line} strokeWidth={on && highlighted ? 2 : 1} opacity={on ? 1 : 0.15} />;
              })}
              {graph.nodes.map((n) => {
                const on = !highlighted || (connected && connected.has(n.id));
                const label = n.label.length > 20 ? n.label.slice(0, 19) + "…" : n.label;
                return (
                  <g key={n.id} onClick={() => setHighlighted(highlighted === n.id ? null : n.id)} style={{ cursor: "pointer", opacity: on ? 1 : 0.25 }}>
                    <circle cx={n.x} cy={n.y} r={9} fill={GRAPH_COLORS[n.type]} stroke={T.panel} strokeWidth={2} />
                    <text x={n.x} y={n.y + 20} textAnchor="middle" style={{ fontSize: 10, fontFamily: "'Inter', sans-serif", fill: T.inkSoft }}>{label}</text>
                  </g>
                );
              })}
            </svg>
            <div className="flex flex-wrap gap-4 mt-3" style={{ ...sans, fontSize: 12, color: T.inkSoft }}>
              {[["editora", "Editora"], ["colecao", "Coleção"], ["obra", "Obra"], ["pessoa", "Pessoa"], ["personagem", "Personagem"]].map(([k, label]) => (
                <span key={k} className="flex items-center gap-1.5">
                  <span style={{ display: "inline-block", width: 9, height: 9, borderRadius: "50%", backgroundColor: GRAPH_COLORS[k] }}></span>{label}
                </span>
              ))}
            </div>
            <p style={{ ...sans, fontSize: 11, color: T.inkSoft }} className="mt-2">Clique em um nó pra destacar só as conexões dele.</p>
          </div>
        </Card>
      )}
    </div>
  );
}

const NAV = [
  { key: "home", label: "Início" },
  { key: "dashboard", label: "Dashboard" },
  { key: "acervo", label: "Acervo" },
  { key: "obras", label: "Obras" },
  { key: "editoras", label: "Editoras" },
  { key: "colecoes", label: "Coleções" },
  { key: "pessoas", label: "Pessoas" },
  { key: "personagens", label: "Personagens" },
  { key: "leituras", label: "Leituras" },
  { key: "wishlist", label: "Wishlist" },
  { key: "grafo", label: "Grafo" },
  { key: "relatorios", label: "Relatórios" },
];

export default function App() {
  const [itensState, setItensState] = usePersistentState("acervo_itens", DATA.itens);
  const [editorasState, setEditorasState] = usePersistentState("acervo_editoras", DATA.editoras);
  const [colecoesState, setColecoesState] = usePersistentState("acervo_colecoes", DATA.colecoes);
  const [pessoasState, setPessoasState] = usePersistentState("acervo_pessoas", DATA.pessoas);
  const [personagensState, setPersonagensState] = usePersistentState("acervo_personagens", []);
  const [wishlistState, setWishlistState] = usePersistentState("acervo_wishlist", []);
  const [leiturasState, setLeiturasState] = usePersistentState("acervo_leituras", DATA.leituras);
  const categorias = useMemo(() => [...new Set(itensState.map((i) => i.categoria))].filter(Boolean).sort(), [itensState]);
  const lk = useLookups(itensState, editorasState, colecoesState, leiturasState, pessoasState, personagensState);
  const obras = useObras(itensState);

  const [view, setView] = useState("home");
  const [syncStatus, setSyncStatus] = useState("idle");
  const [syncMsg, setSyncMsg] = useState("");
  const [editoraSel, setEditoraSel] = useState(null);
  const [colecaoSel, setColecaoSel] = useState(null);
  const [obraSel, setObraSel] = useState(null);
  const [pessoaSel, setPessoaSel] = useState(null);
  const [personagemSel, setPersonagemSel] = useState(null);
  const [editingItemId, setEditingItemId] = useState(null);
  const [history, setHistory] = useState([]);

  const pushHistory = () => {
    setHistory((h) => [...h, { view, editoraSel, colecaoSel, obraSel, pessoaSel, personagemSel }]);
  };
  const goBack = () => {
    setHistory((h) => {
      if (h.length === 0) return h;
      const prev = h[h.length - 1];
      setView(prev.view);
      setEditoraSel(prev.editoraSel);
      setColecaoSel(prev.colecaoSel);
      setObraSel(prev.obraSel);
      setPessoaSel(prev.pessoaSel);
      setPersonagemSel(prev.personagemSel);
      return h.slice(0, -1);
    });
  };

  const goEditora = (id) => { pushHistory(); setEditoraSel(id); setView("editoras"); };
  const goColecao = (id) => { pushHistory(); setColecaoSel(id); setView("colecoes"); };
  const goObra = (id) => { pushHistory(); setObraSel(id); setView("obras"); };
  const goPessoa = (id) => { pushHistory(); setPessoaSel(id); setView("pessoas"); };
  const goPersonagem = (id) => { pushHistory(); setPersonagemSel(id); setView("personagens"); };

  const changeView = (key) => {
    pushHistory();
    setView(key);
    if (key !== "editoras") setEditoraSel(null);
    if (key !== "colecoes") setColecaoSel(null);
    if (key !== "obras") setObraSel(null);
    if (key !== "pessoas") setPessoaSel(null);
    if (key !== "personagens") setPersonagemSel(null);
  };

  const toggleLido = (itemId) => {
    setLeiturasState((prev) => {
      const existing = prev.find((l) => l.itemId === itemId);
      if (existing) return prev.filter((l) => l.itemId !== itemId);
      return [...prev, { id: nextId(prev, "LEI-", 6), itemId, status: "Lido", nota: "", favorito: "", releitura: "Não" }];
    });
  };

  const pushToSheets = async () => {
    if (!window.confirm("Isso vai substituir o conteúdo da planilha pelo que está aqui no navegador agora. Continuar?")) return;
    setSyncStatus("loading"); setSyncMsg("Enviando para o Sheets...");
    try {
      const payload = {
        itens: itensState, editoras: editorasState, colecoes: colecoesState,
        pessoas: pessoasState, personagens: personagensState, leituras: leiturasState, wishlist: wishlistState,
      };
      const res = await fetch(SHEETS_API_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (data.ok) { setSyncStatus("success"); setSyncMsg("Enviado! Os dados desta tela agora estão salvos na planilha."); }
      else { setSyncStatus("error"); setSyncMsg("A planilha respondeu, mas algo deu errado ao salvar."); }
    } catch (err) {
      setSyncStatus("error"); setSyncMsg("Não consegui falar com o Sheets agora. Confira sua internet e tente de novo.");
    }
  };

  const pullFromSheets = async () => {
    if (!window.confirm("Isso vai substituir o que está na tela pelo conteúdo atual da planilha. Continuar?")) return;
    setSyncStatus("loading"); setSyncMsg("Carregando do Sheets...");
    try {
      const res = await fetch(SHEETS_API_URL);
      const data = await res.json();
      setItensState(data.itens || []);
      setEditorasState(data.editoras || []);
      setColecoesState(data.colecoes || []);
      setPessoasState(data.pessoas || []);
      setPersonagensState(data.personagens || []);
      setLeiturasState(data.leituras || []);
      setWishlistState(data.wishlist || []);
      setSyncStatus("success"); setSyncMsg("Carregado! Os dados da planilha estão na tela agora.");
    } catch (err) {
      setSyncStatus("error"); setSyncMsg("Não consegui carregar do Sheets agora. Confira sua internet e tente de novo.");
    }
  };

  const handleAddItem = (form) => {
    const entries = [];
    let editoras = editorasState;
    let editoraNacId = "";
    if (form.editoraNacional.trim()) { const r = findOrCreate(form.editoraNacional, editoras, "EDIT-", 4, { ambito: "Nacional" }); editoraNacId = r.id; editoras = r.list; entries.push({ tipo: "EDITORA", nome: r.nome, novo: r.created }); }
    let editoraIntId = "";
    if (form.editoraInternacional.trim()) { const r = findOrCreate(form.editoraInternacional, editoras, "EDIT-", 4, { ambito: "Internacional" }); editoraIntId = r.id; editoras = r.list; entries.push({ tipo: "EDITORA", nome: r.nome, novo: r.created }); }
    let colecoes = colecoesState;
    let colecaoId = "";
    if (form.colecao.trim()) { const r = findOrCreate(form.colecao, colecoes, "COL-", 4, { editoraId: editoraNacId }); colecaoId = r.id; colecoes = r.list; entries.push({ tipo: "COLEÇÃO", nome: r.nome, novo: r.created }); }
    let pessoas = pessoasState;
    const funcaoArgumento = roleForFormato(form.formato);
    const roteiristaIds = [];
    splitNames(form.argumento).forEach((nome) => { const r = findOrCreate(nome, pessoas, "PES-", 4, {}); roteiristaIds.push(r.id); pessoas = r.list; entries.push({ tipo: `PESSOA · ${funcaoArgumento.toUpperCase()}`, nome: r.nome, novo: r.created }); });
    const artistaIds = [];
    splitNames(form.artista).forEach((nome) => { const r = findOrCreate(nome, pessoas, "PES-", 4, {}); artistaIds.push(r.id); pessoas = r.list; entries.push({ tipo: "PESSOA · ARTISTA", nome: r.nome, novo: r.created }); });
    let personagens = personagensState;
    const personagemIds = [];
    splitNames(form.personagens).forEach((nome) => { const r = findOrCreate(nome, personagens, "PER-", 4, {}); personagemIds.push(r.id); personagens = r.list; entries.push({ tipo: "PERSONAGEM", nome: r.nome, novo: r.created }); });

    const newItem = { id: nextId(itensState, "ITEM-", 6), titulo: form.titulo.trim(), formato: form.formato, encadernacao: form.encadernacao.trim(), categoria: form.categoria.trim(), genero: form.genero.trim(), colecaoId, editoraNacId, editoraIntId, roteiristaIds, artistaIds, personagemIds };
    setEditorasState(editoras); setColecoesState(colecoes); setPessoasState(pessoas); setPersonagensState(personagens);
    setItensState((prev) => [newItem, ...prev]);
    return { titulo: newItem.titulo, entries };
  };

  const handleSaveEdit = (form) => {
    let editoras = editorasState;
    let editoraNacId = "";
    if (form.editoraNacional.trim()) { const r = findOrCreate(form.editoraNacional, editoras, "EDIT-", 4, { ambito: "Nacional" }); editoraNacId = r.id; editoras = r.list; }
    let editoraIntId = "";
    if (form.editoraInternacional.trim()) { const r = findOrCreate(form.editoraInternacional, editoras, "EDIT-", 4, { ambito: "Internacional" }); editoraIntId = r.id; editoras = r.list; }
    let colecoes = colecoesState;
    let colecaoId = "";
    if (form.colecao.trim()) { const r = findOrCreate(form.colecao, colecoes, "COL-", 4, { editoraId: editoraNacId }); colecaoId = r.id; colecoes = r.list; }
    setEditorasState(editoras); setColecoesState(colecoes);
    setItensState((prev) => prev.map((it) => it.id === editingItemId ? {
      ...it, titulo: form.titulo.trim(), formato: form.formato, encadernacao: form.encadernacao.trim(),
      categoria: form.categoria.trim(), genero: form.genero.trim(), colecaoId, editoraNacId, editoraIntId,
    } : it));
    setEditingItemId(null);
  };

  const editingItem = editingItemId ? itensState.find((it) => it.id === editingItemId) : null;

  let content;
  if (view === "home") content = <Home itens={itensState} editoras={editorasState} colecoes={colecoesState} pessoas={pessoasState} personagens={personagensState} obras={obras} wishlist={wishlistState} lk={lk} onNavigate={changeView} />;
  else if (view === "dashboard") content = <Dashboard lk={lk} itens={itensState} editoras={editorasState} />;
  else if (view === "acervo") content = <Acervo lk={lk} onEditoraClick={goEditora} onColecaoClick={goColecao} onObraClick={goObra} itens={itensState} editoras={editorasState} colecoes={colecoesState} pessoas={pessoasState} personagens={personagensState} categorias={categorias} onAddItem={handleAddItem} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "obras") content = <ObrasView obras={obras} lk={lk} editoras={editorasState} selected={obraSel} onSelect={goObra} onEditoraClick={goEditora} onColecaoClick={goColecao} onPessoaClick={goPessoa} onPersonagemClick={goPersonagem} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "editoras") content = <EditorasView lk={lk} editoras={editorasState} selected={editoraSel} onSelect={goEditora} onColecaoClick={goColecao} onObraClick={goObra} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "colecoes") content = <ColecoesView lk={lk} colecoes={colecoesState} itens={itensState} editoras={editorasState} selected={colecaoSel} onSelect={goColecao} onEditoraClick={goEditora} onObraClick={goObra} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "pessoas") content = <PessoasView pessoas={pessoasState} itens={itensState} lk={lk} selected={pessoaSel} onSelect={goPessoa} onObraClick={goObra} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "personagens") content = <PersonagensView personagens={personagensState} setPersonagens={setPersonagensState} itens={itensState} setItens={setItensState} lk={lk} selected={personagemSel} onSelect={goPersonagem} onObraClick={goObra} onToggleLido={toggleLido} onEdit={setEditingItemId} />;
  else if (view === "leituras") content = <LeiturasView lk={lk} itens={itensState} leituras={leiturasState} onToggleLido={toggleLido} onObraClick={goObra} />;
  else if (view === "wishlist") content = <WishlistView wishlist={wishlistState} setWishlist={setWishlistState} />;
  else if (view === "grafo") content = <GrafoView obras={obras} editoras={editorasState} colecoes={colecoesState} lk={lk} />;
  else if (view === "relatorios") content = <RelatoriosView itens={itensState} editoras={editorasState} colecoes={colecoesState} personagens={personagensState} lk={lk} />;

  return (
    <div style={{ ...sans, backgroundColor: T.bg, minHeight: "100vh", color: T.ink }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        button, a, select, input, textarea, tr, .transition-soft {
          transition: background-color 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, transform 0.18s ease, color 0.18s ease, opacity 0.18s ease;
        }
      `}</style>
      {editingItem && (
        <EditItemModal
          item={editingItem}
          editoras={editorasState}
          colecoes={colecoesState}
          categorias={categorias}
          generos={[...new Set(itensState.map((i) => i.genero))].filter(Boolean).sort()}
          onCancel={() => setEditingItemId(null)}
          onSave={handleSaveEdit}
        />
      )}
      <div className="flex">
        <aside className="hidden md:flex flex-col shrink-0" style={{ width: 230, borderRight: `1px solid ${T.line}`, backgroundColor: T.panel, minHeight: "100vh" }}>
          <button onClick={() => changeView("home")} className="text-left px-4 pt-4 pb-4" style={{ borderBottom: `1px solid ${T.line}` }}>
            <img src="/logo/logo.png" alt={ACERVO_NOME} className="w-full" style={{ maxWidth: 190, display: "block", margin: "0 auto" }} />
          </button>
          <nav className="py-2 px-2 flex-1 overflow-y-auto">
            {NAV.map((n) => {
              const active = view === n.key;
              return (
                <button key={n.key} onClick={() => changeView(n.key)} className="w-full text-left px-3 py-2 rounded-md text-sm mb-0.5"
                  style={{ ...sans, color: active ? "#fff" : T.inkSoft, backgroundColor: active ? T.accent : "transparent" }}>
                  {n.label}
                </button>
              );
            })}
          </nav>
          <div className="px-3 pb-3 space-y-2">
            <button onClick={pushToSheets} disabled={syncStatus === "loading"} className="w-full flex items-center justify-center gap-2 px-3 py-2 rounded-md text-sm" style={{ ...sans, border: `1px solid ${T.line}`, color: T.accent, backgroundColor: T.bg }}>
              <RefreshCw size={14} /> Enviar para o Sheets
            </button>
            <button onClick={pullFromSheets} disabled={syncStatus === "loading"} className="w-full flex items-center justify-center gap-2 px-3 py-2 rounded-md text-sm" style={{ ...sans, border: `1px solid ${T.line}`, color: T.inkSoft, backgroundColor: T.bg }}>
              <RefreshCw size={14} /> Carregar do Sheets
            </button>
            {syncMsg && (
              <p style={{ ...sans, fontSize: 11, color: syncStatus === "error" ? "#9C4530" : T.deep }} className="px-1">{syncMsg}</p>
            )}
          </div>
          <div className="px-4 py-3" style={{ borderTop: `1px solid ${T.line}`, ...mono, fontSize: 10, color: T.inkSoft }}>{itensState.length} itens · protótipo v0.18</div>
        </aside>
        <main className="flex-1 px-5 md:px-8 py-6 md:py-8">
          <div className="max-w-5xl mx-auto relative">
            {HERO_BY_VIEW[view] && (() => {
              const cfg = HERO_BY_VIEW[view];
              const sidePos = cfg.side === "left" ? { left: cfg.inset ?? 0 } : { right: cfg.inset ?? 0 };
              return (
                <img
                  src={`/heroes/${cfg.file}`}
                  alt=""
                  className="hidden md:block absolute pointer-events-none select-none"
                  style={{
                    top: cfg.top ?? -18,
                    ...sidePos,
                    height: cfg.height ?? 130,
                    transform: cfg.flip ? "scaleX(-1)" : undefined,
                    zIndex: 0,
                  }}
                />
              );
            })()}
            <div style={{ position: "relative", zIndex: 1 }}>
              {history.length > 0 && (
                <button onClick={goBack} className="flex items-center gap-1 mb-4 text-sm" style={{ ...sans, color: T.inkSoft }}>
                  <ArrowLeft size={14} /> Voltar
                </button>
              )}
              {content}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
